def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    cells = [(r, c) for r in range(h) for c in range(w) if src[r][c] == 4]
    if not cells:
        return out

    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = {(r - r0, c - c0) for r, c in cells}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    for color in range(10):
        if color in (1, 4):
            continue
        remaining = {(r, c) for r in range(h) for c in range(w)
                     if src[r][c] == color}

        while len(remaining) >= 2:
            candidates = set()
            for r, c in remaining:
                for dr, dc in shape:
                    ar, ac = r - dr, c - dc
                    if 0 <= ar and ar + sh <= h and 0 <= ac and ac + sw <= w:
                        candidates.add((ar, ac))

            best = None
            for ar, ac in candidates:
                matched = {(r, c) for r, c in remaining
                           if (r - ar, c - ac) in shape}
                if len(matched) < 2:
                    continue
                key = (-len(matched), ar, ac)
                if best is None or key < best[0]:
                    best = (key, ar, ac, matched)

            if best is None:
                break

            _, ar, ac, matched = best
            for dr, dc in shape:
                r, c = ar + dr, ac + dc
                if src[r][c] == 1:
                    out[r][c] = color
            remaining -= matched

    return out
